/** Actual card + actual settings integration, with only the canvas/host boundary replaced by recording fakes. */
public final class GlobalResultsRendererTest {
    static int checks;static List<String> groups=new ArrayList<>();
    static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    static void eq(Object actual,Object expected,String message){checks++;if(!Objects.equals(actual,expected))throw new AssertionError(message+" expected="+expected+" actual="+actual);}
    static void near(double actual,double expected,String message){checks++;if(Math.abs(actual-expected)>.00001)throw new AssertionError(message+" expected="+expected+" actual="+actual);}
    static void test(String name,Runnable run){run.run();groups.add(name);}
    public static void main(String[] args){
        test("four-column-density-rounding-and-source-spacing",GlobalResultsRendererTest::layout);
        test("real-mod-card-open-toggle-favorite-hide-and-stale-click",GlobalResultsRendererTest::cards);
        test("actual-setting-leaf-multiline-menu-reset-and-owner-lock",GlobalResultsRendererTest::settings);
        test("actual-accordion-whole-child-and-owner-namespace",GlobalResultsRendererTest::accordion);
        test("actual-keybind-recording-and-global-input-forwarding",GlobalResultsRendererTest::recording);
        test("waiting-empty-clipping-query-scroll-and-missing-card",GlobalResultsRendererTest::messages);
        System.out.println("GlobalResultsRendererTest PASS: "+groups.size()+" groups, "+checks+" assertions");groups.forEach(name->System.out.println("PASS "+name));
    }
    static LibraryMods.Card card(String id,AtomicInteger opened,AtomicBoolean enabled){return new LibraryMods.Card(id,"Card "+id,"Description "+id,"hud","hud","","",null,enabled::get,enabled::set,c->opened.incrementAndGet());}
    static SearchIndex.Document<?> document(LibraryMods.Card card){return SearchDocuments.mod(card.id(),card.title(),card.description(),"HUD",null,List.of(),card);}
    static SearchPage.Results result(String query,List<SearchIndex.Document<?>> mods,Map<String,List<SearchDocuments.NarrowedRow>> groups){return new SearchPage.Results(query,mods,groups);}
    static void layout(){
        Host host=new Host();for(int i=0;i<6;i++)host.cards.add(card("m"+i,new AtomicInteger(),new AtomicBoolean(true)));Context c=new Context(host);GlobalResultsRenderer renderer=new GlobalResultsRenderer();c.frame(renderer,result("m",host.cards.stream().map(GlobalResultsRendererTest::document).toList(),Map.of()));
        Rect first=c.hit("mods.card.m0").bounds,last=c.hit("mods.card.m3").bounds,next=c.hit("mods.card.m4").bounds;
        near(first.w(),255,"integer pixel cell width from (1077-57)/4");near(first.x(),c.bounds.x(),"PageContext already includes source 25dp horizontal gutter");near(first.y(),c.bounds.y()+11+4+8,"11sp mod header +4 bottom +8 list gap");near(last.x(),first.x()+3*(255+19),"fourth column physical position");near(next.y()-first.y(),140+19,"between mod rows combines 8+11 gaps");near(first.h(),140,"actual source card height");
        check(c.painter.weighted.stream().anyMatch(t->t.text.equals("MODS")&&t.size==11&&t.weight==500),"source header Medium 500, not synthetic bold");near(GlobalResultsRenderer.modCellWidth(1000,1.5),(1500-3*29)/4/1.5,"integer remainder under fractional density");near(GlobalResultsRenderer.modGap(1.5),29/1.5,"rounded physical column gap");check(c.painter.depth==0,"all canvas saves balanced");eq(c.content(),new Rect(289,88,1077,587),"viewport restored");
    }
    static void cards(){
        Host host=new Host();AtomicInteger opened=new AtomicInteger();AtomicBoolean enabled=new AtomicBoolean(true);LibraryMods.Card actual=card("muonium.hud",opened,enabled);host.cards.add(actual);Context c=new Context(host);GlobalResultsRenderer renderer=new GlobalResultsRenderer();SearchIndex.Document<?> owner=SearchDocuments.mod("muonium","old settings corpus",null,null,null,List.of(),new SearchDocuments.Owner("muonium","MuoniumPlayer"));SearchPage.Results result=result("settings",List.of(owner),Map.of());
        c.frame(renderer,result);Rect card=c.hit("mods.card.muonium.hud").bounds;c.click("mods.toggle.muonium.hud");check(!enabled.get(),"actual card live toggle changed");eq(host.persists,1,"real card toggle persists host");c.click("mods.favorite.muonium.hud");check(c.preferences.favorite("irrelevant")==false&&c.preferences.flag("mods.favorite.muonium.hud",false),"actual card favorite namespace");c.click("mods.hidden.muonium.hud");check(c.preferences.flag("mods.hidden.muonium.hud",false),"actual hide action updates existing prefs");
        c.click("mods.card.muonium.hud");c.release();eq(opened.get(),1,"card release opens actual route callback");
        c.frame(renderer,result);c.click("mods.card.muonium.hud");c.mx+=10;c.updateDrag();c.release();eq(opened.get(),1,"search card movement cancels click without list reordering");
        c.frame(renderer,result);c.click("mods.card.muonium.hud");renderer.results(c,result("other",List.of(owner),Map.of()));c.release();eq(opened.get(),1,"new results invalidate old pending card release");
        c.frame(renderer,result);c.click("mods.card.muonium.hud");renderer.leave(c);c.release();eq(opened.get(),1,"leaving results invalidates pending route click");
    }
    static ConfigHost.Option option(String id,String title,AtomicReference<Object> value){return new ConfigHost.Option(id,title,"Description",ConfigHost.Kind.TOGGLE,0,100,1,List.of("One","Two"),value::get,value::set,()->"",()->value.set(false));}
    static SearchDocuments.SettingsSnapshot snapshot(String owner,List<ConfigHost.Option> options,SearchDocuments.SettingsAdapter adapter){return SearchDocuments.settings(owner,"Owner "+owner,List.of(new ConfigHost.Category("category","Category","","",List.of(new ConfigHost.Group("group","General",options)))),adapter);}
    static SearchPage.Results options(String query,SearchDocuments.SettingsSnapshot snapshot){return result(query,List.of(),snapshot.rows().globalGroups(snapshot.documents().stream().filter(d->!d.scopes().contains(SearchIndex.Scope.MODS)).toList()));}
    static void settings(){
        Host host=new Host();AtomicReference<Object> value=new AtomicReference<>(false);ConfigHost.Option toggle=option("switch","Visible switch",value);host.categories=List.of(new ConfigHost.Category("c","Category","","",List.of(new ConfigHost.Group("g","General",List.of(toggle)))));SearchDocuments.SettingsSnapshot snap=snapshot("alpha",List.of(toggle),SearchDocuments.DEFAULT);Context c=new Context(host);GlobalResultsRenderer renderer=new GlobalResultsRenderer();SearchPage.Results hits=options("visible",snap);
        c.frame(renderer,hits);String key=c.find("settings.toggle.switch");Rect row=c.painter.layers.stream().filter(l->l.bounds.w()==c.bounds.w()&&l.alpha==1).map(l->l.bounds).findFirst().orElseThrow();near(row.y(),c.bounds.y()+8+11+2+8,"group header top8 +11sp +bottom2 +list8");c.click(key);eq(value.get(),true,"actual SettingsPage toggle setter used");eq(c.edited,toggle,"real Option identity preserved");
        c.frame(renderer,hits);c.mx=row.x()+20;c.my=row.y()+10;check(renderer.pointerDown(c,1),"actual setting right-click opens original menu");check(c.overlay!=null,"original OptionMenu, not a duplicate search menu");c.overlay.render(c);check(c.painter.texts.stream().anyMatch(s->s.text.equals("Reset to default")),"real reset menu rendered");c.click(c.find("settings.menu.switch.0"));eq(value.get(),false,"actual menu reset updates original option");
        SettingsSchema locked=new SettingsSchema(){public boolean locked(){return true;}};GlobalResultsRenderer lockedRenderer=new GlobalResultsRenderer(owner->locked);c.frame(lockedRenderer,hits);check(c.painter.layers.stream().anyMatch(l->Math.abs(l.alpha-.45)<.0001),"owner disabled layer exactly .45");check(c.hits.keySet().stream().noneMatch(s->s.endsWith("settings.toggle.switch")),"disabled owner cannot edit control");
        SettingsSchema own=new SettingsSchema(){public boolean locked(){return true;}public String lockExemptId(){return toggle.id();}};GlobalResultsRenderer ownRenderer=new GlobalResultsRenderer(owner->own);c.frame(ownRenderer,hits);check(c.hits.keySet().stream().anyMatch(s->s.endsWith("settings.toggle.switch")),"own switch exempt by actual stable ID");
        AtomicReference<Object> text=new AtomicReference<>("one\ntwo\nthree\nfour");ConfigHost.Option textOption=option("long","Text with lines",text);SearchDocuments.SettingsSnapshot texts=snapshot("text",List.of(textOption),SearchDocuments.DEFAULT);SettingsSchema schema=new SettingsSchema(){public OptionStyle option(ConfigHost.Option o){OptionStyle style=new OptionStyle(Visualizer.TEXT);style.multiline=true;return style;}};GlobalResultsRenderer textRenderer=new GlobalResultsRenderer(owner->schema);c.frame(textRenderer,options("text",texts));double textHeight=c.painter.layers.stream().mapToDouble(l->l.bounds.h()).max().orElse(0);check(textHeight>row.h(),"variable multiline row measured by actual shared renderer");
    }
    static void accordion(){
        Host host=new Host();ConfigHost.Option a=option("same","Alpha child",new AtomicReference<>(false)),b=option("other","Beta child",new AtomicReference<>(false));ConfigHost.Group group=new ConfigHost.Group("panel","Accordion",List.of(a,b));ConfigHost.Category category=new ConfigHost.Category("c","C","","",List.of(group));SearchDocuments.SettingsAdapter adapter=new SearchDocuments.SettingsAdapter(){public SearchDocuments.GroupData group(ConfigHost.Category c,ConfigHost.Group g){return new SearchDocuments.GroupData(true,null,true,List.of());}};SearchDocuments.SettingsSnapshot snap=SearchDocuments.settings("accordion","Accordion owner",List.of(category),adapter);SettingsSchema schema=new SettingsSchema(){public GroupStyle group(ConfigHost.Group g){return new GroupStyle(true,false,null,"Details","");}};Context c=new Context(host);GlobalResultsRenderer renderer=new GlobalResultsRenderer(owner->schema);
        SearchIndex.Document<?> child=snap.documents().stream().filter(d->d.payload()==a).findFirst().orElseThrow();c.frame(renderer,result("child",List.of(),snap.rows().globalGroups(List.of(child))));check(c.painter.texts.stream().anyMatch(t->t.text.equals("Alpha child")),"child match renders through actual accordion");check(c.painter.texts.stream().noneMatch(t->t.text.equals("Beta child")),"unmatched body child omitted");
        SearchIndex.Document<?> tree=snap.documents().stream().filter(d->d.payload()==group).findFirst().orElseThrow();c.frame(renderer,result("whole",List.of(),snap.rows().globalGroups(List.of(tree))));check(c.painter.texts.stream().anyMatch(t->t.text.equals("Beta child")),"whole accordion hit reuses all body controls");
        SearchDocuments.SettingsSnapshot left=snapshot("left",List.of(a),SearchDocuments.DEFAULT),right=snapshot("right",List.of(option("same","Right owner",new AtomicReference<>(false))),SearchDocuments.DEFAULT);LinkedHashMap<String,List<SearchDocuments.NarrowedRow>> both=new LinkedHashMap<>(left.rows().globalGroups(left.documents()));both.putAll(right.rows().globalGroups(right.documents()));c.frame(new GlobalResultsRenderer(),result("both",List.of(),both));eq(c.hits.keySet().stream().filter(s->s.endsWith("settings.toggle.same")).count(),2L,"two actual owners with same local stable ID remain isolated");
    }
    static void recording(){
        Host host=new Host();AtomicReference<Object> value=new AtomicReference<>(SettingsSchema.Binding.none());ConfigHost.Option option=option("bind","Bind",value);SettingsSchema schema=new SettingsSchema(){public OptionStyle option(ConfigHost.Option o){return new OptionStyle(Visualizer.KEYBIND);}public String keyName(int code){return "K"+code;}};SearchDocuments.SettingsSnapshot snap=snapshot("keys",List.of(option),SearchDocuments.DEFAULT);Context c=new Context(host);GlobalResultsRenderer renderer=new GlobalResultsRenderer(owner->schema);c.frame(renderer,options("bind",snap));String recording=c.hits.keySet().stream().filter(id->id.toLowerCase(Locale.ROOT).contains("keybind")||id.toLowerCase(Locale.ROOT).contains("record")).findFirst().orElseThrow(()->new AssertionError("No actual keybind hit: "+c.hits.keySet()));c.click(recording);check(renderer.recording(),"global renderer reports actual key recording for shortcut avoidance");check(renderer.rawKey(c,65,true),"raw key press forwarded to real recorder");check(renderer.rawKey(c,65,false),"raw key release forwarded");check(!renderer.recording(),"recording ends after all releases");check(value.get() instanceof SettingsSchema.Binding binding&&binding.keys().equals(List.of(65)),"actual binding setter receives recorded code");renderer.leave(c);check(!renderer.recording(),"leaving clears global recording flag");
    }
    static void messages(){
        Host host=new Host();Context c=new Context(host);GlobalResultsRenderer renderer=new GlobalResultsRenderer();c.begin();renderer.searching(c);c.end();check(c.painter.weighted.stream().anyMatch(t->t.text.equals("Searching...")&&t.size==15&&t.weight==400),"first pending uses source15sp centered text");
        c.frame(renderer,result("none",List.of(),Map.of()));check(c.painter.weighted.stream().anyMatch(t->t.text.equals("No results for \"none\"")),"source translated no-results query");
        for(int i=0;i<20;i++)host.cards.add(card("m"+i,new AtomicInteger(),new AtomicBoolean(true)));SearchPage.Results many=result("many",host.cards.stream().map(GlobalResultsRendererTest::document).toList(),Map.of());c.frame(renderer,many);check(c.maximum>0,"content scroll range measured from actual rows");c.scroll=80;c.frame(renderer,many);near(c.scroll,80,"same completed query preserves scroll");SearchPage.Results changed=result("next",many.mods(),Map.of());c.frame(renderer,changed);near(c.scroll,0,"only new completed query resets scroll");
        c.scroll=100;c.frame(renderer,changed);for(Context.Hit hit:c.hits.values())check(hit.bounds.x()>=c.bounds.x()&&hit.bounds.y()>=c.bounds.y()&&hit.bounds.right()<=c.bounds.right()+.00001&&hit.bounds.bottom()<=c.bounds.bottom()+.00001,"all card hit boxes clipped to content");
        c.frame(renderer,result("missing",List.of(SearchDocuments.mod("not-registered","Missing",null,null,null,List.of(),new Object())),Map.of()));eq(host.errors,1,"missing card is diagnosed, not synthesized");check(c.painter.weighted.stream().anyMatch(t->t.text.contains("Search failed")),"missing card presents explicit error result");check(c.painter.depth==0,"canvas balanced even when missing real card");
    }
    static final class Host implements ConfigHost,LibraryServices.ModCatalog,SettingsSchema.Provider{
        List<Category> categories=List.of();List<LibraryMods.Card> cards=new ArrayList<>();int persists,errors;String clipboard="";
        public List<Category> categories(){return categories;}public List<HudElement> huds(){return List.of();}public void persist(){persists++;}public void close(){}public String clipboard(){return clipboard;}public void clipboard(String value){clipboard=value;}public void error(String action,Throwable error){errors++;}public List<LibraryMods.Card> modCards(){return cards;}public SettingsSchema settingsSchema(){return SettingsSchema.DEFAULT;}
    }
    static final class Context implements PageContext {
        record Hit(Rect bounds,Runnable action){}final Host host;final Draw painter=new Draw();final UiPreferences preferences=new UiPreferences(Map.of(),()->{});final LinkedHashMap<String,Hit> hits=new LinkedHashMap<>();Rect bounds=new Rect(289,88,1077,587);double scroll,maximum,mx=-20,my=-20;UiPage overlay;BiConsumer<Double,Double> drag;Runnable finish;ConfigHost.Option edited;
        Context(Host host){this.host=host;}void begin(){hits.clear();painter.clear();}void end(){check(painter.depth==0,"balanced paint after frame");eq(bounds,new Rect(289,88,1077,587),"content preserved after frame");}void frame(GlobalResultsRenderer renderer,SearchPage.Results result){begin();renderer.results(this,result);end();}Hit hit(String id){Hit hit=hits.get(id);if(hit==null)throw new AssertionError("Missing hit "+id+": "+hits.keySet());return hit;}String find(String suffix){return hits.keySet().stream().filter(s->s.endsWith(suffix)).findFirst().orElseThrow(()->new AssertionError("Missing suffix "+suffix+": "+hits.keySet()));}void click(String id){Hit hit=hit(id);mx=hit.bounds.x()+hit.bounds.w()/2;my=hit.bounds.y()+hit.bounds.h()/2;hit.action.run();}void updateDrag(){if(drag!=null)drag.accept(mx,my);}void release(){Runnable end=finish;drag=null;finish=null;if(end!=null)end.run();}
        public Painter painter(){return painter;}public Theme theme(){return Theme.BUILTIN[0];}public int accent(){return 0xff2b4bff;}public ConfigHost host(){return host;}public UiPreferences preferences(){return preferences;}public String query(){return "";}public Navigation.Route route(){return new Navigation.Route(Navigation.Page.MODS);}public double mouseX(){return mx;}public double mouseY(){return my;}public double width(){return 1391;}public double height(){return 700;}public double time(){return 20;}public double delta(){return .016;}public boolean control(){return false;}public boolean shift(){return false;}public boolean alt(){return false;}public int nativeKeyCode(){return 0;}public boolean textFocused(){return false;}public Rect content(){return bounds;}public void content(Rect r){bounds=r;}public double scroll(){return scroll;}public void scroll(double n){scroll=Math.max(0,n);}public void scrollRange(double maximum){this.maximum=maximum;scroll=Math.min(scroll,maximum);}public void hit(String id,Rect r,Runnable action,String tip){if(r.w()>0&&r.h()>0)hits.put(id,new Hit(r,action));}public void contentHit(String id,Rect r,Runnable action,String tip){double x=Math.max(r.x(),bounds.x()),y=Math.max(r.y(),bounds.y()),right=Math.min(r.right(),bounds.right()),bottom=Math.min(r.bottom(),bounds.bottom());if(right>x&&bottom>y)hit(id,new Rect(x,y,right-x,bottom-y),action,tip);}public void tooltip(String id,Rect r,String text){}public void startDrag(BiConsumer<Double,Double> update,Runnable end){drag=update;finish=end;}public void navigate(Navigation.Route route){}public void toast(String text){}public void sound(String event){}public void edit(ConfigHost.Option option,Object value){edited=option;option.set(value);}public void beginEdit(String name){}public void commitEdit(){}public void cancelEdit(){}public void textField(String id,TextEdit edit,Rect r,String placeholder,Consumer<String> changed){}public void textDialog(String title,String hint,String initial,String action,Consumer<String> submit){}public void confirm(String title,String description,Runnable accepted){}public void overlay(UiPage overlay){this.overlay=overlay;}public void dismissOverlay(){if(overlay!=null){UiPage old=overlay;overlay=null;old.leave(this);}}public void close(){}public double animate(String key,double target,double seconds,Motion.Easing easing){return target;}
    }
    static final class Draw implements Painter,NotificationTypography {
        record Text(String text,double x,double y,double size,int weight){}record Layer(Rect bounds,double alpha){}List<Text> texts=new ArrayList<>(),weighted=new ArrayList<>();List<Layer> layers=new ArrayList<>();int depth;
        void clear(){texts.clear();weighted.clear();layers.clear();}public void save(){depth++;}public void restore(){if(--depth<0)throw new AssertionError("unbalanced restore");}public void layer(Rect r,double a){save();layers.add(new Layer(r,a));}public void translate(double x,double y){}public void scale(double x,double y){}public void clip(Rect r,double radius){}public void rect(Rect r,double radius,int color){check(Double.isFinite(r.x())&&Double.isFinite(r.y())&&r.w()>=0&&r.h()>=0,"finite nonnegative rect");}public void outline(Rect r,double radius,double width,int color){}public void line(double x1,double y1,double x2,double y2,double width,int color){}public void text(String text,double x,double y,double size,boolean bold,int color){texts.add(new Text(text,x,y,size,bold?700:400));}public double measure(String text,double size,boolean bold){return text.codePointCount(0,text.length())*size*.5;}public void icon(String id,double x,double y,double size,int color){}public void notificationText(String text,double x,double y,double size,int weight,int color){weighted.add(new Text(text,x,y,size,weight));}public double notificationMeasure(String text,double size,int weight){return text.codePointCount(0,text.length())*size*.5;}
    }
}
